from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult
from azure.core.credentials import AzureKeyCredential
import os
from typing import List, Dict

def extract_tables_and_rows(document_bytes: bytes) -> List[Dict]:
    """
    Extracts table cells and row structure from a document using Azure Document Intelligence.

    Args:
        document_bytes: The bytes content of the document (e.g., PDF, JPG, PNG).

    Returns:
        A list of dictionaries, where each dictionary represents a table and contains
        its rows and cells.
    """
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-layout", document_bytes
    )
    result: AnalyzeResult = poller.result()

    extracted_tables = []
    if result.tables:
        for table_idx, table in enumerate(result.tables):
            current_table_data = {
                "table_id": table_idx,
                "rows": [],
                "bounding_regions": [
                    {
                        "page_number": region.page_number,
                        "polygon": region.polygon
                    }
                    for region in table.bounding_regions
                ] if table.bounding_regions else []
            }

            # Group cells by row_index and then sort by column_index
            rows_data: Dict[int, List[Dict]] = {}
            for cell in table.cells:
                if cell.row_index not in rows_data:
                    rows_data[cell.row_index] = []

                cell_content = cell.content if cell.content is not None else ""

                rows_data[cell.row_index].append({
                    "column_index": cell.column_index,
                    "row_span": cell.row_span if cell.row_span is not None else 1,
                    "column_span": cell.column_span if cell.column_span is not None else 1,
                    "content": cell_content,
                    "bounding_regions": [
                        {
                            "page_number": region.page_number,
                            "polygon": region.polygon
                        }
                        for region in cell.bounding_regions
                    ] if cell.bounding_regions else [],
                    "kind": cell.kind.value if cell.kind else "content" # header, rowHeader, etc.
                })

            # Sort rows by index and cells within each row by column index
            for row_index in sorted(rows_data.keys()):
                sorted_cells = sorted(rows_data[row_index], key=lambda x: x["column_index"])
                current_table_data["rows"].append({
                    "row_index": row_index,
                    "cells": sorted_cells
                })

            extracted_tables.append(current_table_data)

    return extracted_tables
